516	/**
517	 * 主动发起与对端的 WebSocket 连接。
518	 * 流程: 连接 ws://peer_ip:ws_port/ws/chat → 发 connect_request（带 token）→ 等 connect_accepted
519	 */
520	async function connectToPeer(uuid, name, ip) {
521	    // 如果已有活跃连接，直接打开聊天
522	    if (activeChats.has(uuid)) {
523	        openChat(uuid);
524	        return;
525	    }
526	
527	    // 获取对端 ws_port（从在线节点列表）
528	    const peer = onlinePeers.get(uuid);
529	    if (!peer) {
530	        showToast('对方不在线');
531	        return;
532	    }
533	
534	    openChat(uuid); // 先打开聊天窗口，显示"连接中..."
535	
536	    // 连接前先刷新自己的 token（token 每3秒更新，避免用过期的）
537	    try {
538	        const resp = await fetch('/api/me');
539	        const me = await resp.json();
540	        myInfo.token = me.token;
541	    } catch (e) { /* 刷新失败则用现有 token */ }
542	
543	    try {
544	        const peerPort = peer.ws_port || 50002;
545	        const wsUrl = `ws://${peer.ip}:${peerPort}/ws/chat`;
546	        const ws = new WebSocket(wsUrl);
547	
548	        ws.onopen = () => {
549	            // 发送连接请求，带上自己的 token 给对方后端验证
550	            // 对方通过 UDP 广播收到了我的 token，验证是否匹配
551	            ws.send(JSON.stringify({
552	                type: 'connect_request',
553	                uuid: myInfo.uuid,
554	                name: myInfo.name,
555	                token: myInfo.token,
556	                ip: myInfo.ip,
557	                ws_port: myInfo.ws_port,
558	            }));
559	        };
560	
561	        ws.onmessage = (e) => {
562	            const msg = JSON.parse(e.data);
563	            if (msg.type === 'connect_accepted') {
564	                activeChats.set(uuid, ws);
565	                setupPeerMessageHandler(uuid, ws);
566	                addSystemMessage(uuid, '连接已建立');
567	                // 通知自己后端保存联系人（对方后端已保存，自己后端也需要记录）
568	                controlWs.send(JSON.stringify({
569	                    type: 'save_contact',
570	                    uuid: uuid,
571	                    name: name,
572	                    ip: ip,
573	                    ws_port: peer.ws_port || 50002,
574	                }));
575	            } else if (msg.type === 'connect_rejected') {
576	                ws.close();
577	                const reason = msg.reason === 'invalid_token' ? 'Token 验证失败，请稍后重试' : '对方拒绝了连接请求';
578	                addSystemMessage(uuid, reason);
579	                showToast(reason);
580	            }
581	        };
582	
583	        ws.onclose = () => {
584	            activeChats.delete(uuid);
585	            if (currentChat === uuid) {
586	                addSystemMessage(uuid, '连接已断开');
587	                updateChatHeaderStatus();
588	            }
589	        };
590	
591	        ws.onerror = () => {
592	            activeChats.delete(uuid);
593	            addSystemMessage(uuid, '连接失败，请检查网络');
594	            showToast('连接失败');
595	            ws.close();
596	        };
597	
598	    } catch (e) {
599	        addSystemMessage(uuid, `连接失败: ${e.message}`);
600	    }
601	}
