689	                }));
690	                renderOnlineList();
691	                renderContactsList();
692	            } else if (msg.type === 'connect_rejected') {
693	                ws.close();
694	                const reason = msg.reason === 'invalid_token'
695	                    ? 'Token 验证失败，请稍后重试'
696	                    : '对方拒绝了连接请求';
697	                addSystemMessage(tempUuid, reason);
698	                showToast(reason);
699	            }
700	        };
701	
702	        ws.onclose = () => {
703	            activeChats.delete(tempUuid);
704	            if (currentChat === tempUuid) {
705	                addSystemMessage(tempUuid, '连接已断开');
