722	/** 为对端 WS 设置消息处理器（收到 connect_accepted 后调用） */
723	function setupPeerMessageHandler(uuid, ws) {
724	    ws.onmessage = (e) => {
725	        const msg = JSON.parse(e.data);
726	        if (msg.type === 'chat') {
727	            // 对方发来的聊天消息（直接从 ws 收到时也需要处理）
728	            handleDirectChatMessage(uuid, msg);
729	        } else if (msg.type === 'file_response') {
730	            handleFileRequestResponse(msg);
731	        } else if (msg.type === 'file_cancel') {
732	            handleTransferCancelled(msg);
733	        } else if (msg.type === 'ack') {
734	            handleMessageAck(msg);
735	        }
736	    };
737	}
