744	        from: uuid,
745	        content: msg.content,
746	        msg_id: msg.msg_id,
747	        timestamp: msg.timestamp,
748	    });
749	    // chat WS 直连绕过自己后端，需额外通知自己后端保存消息
750	    controlWs.send(JSON.stringify({
751	        type: 'save_message',
752	        peer_uuid: uuid,
753	        sender: uuid,
754	        content: msg.content,
755	        msg_id: msg.msg_id,
756	    }));
757	    if (currentChat === uuid) renderMessages(uuid);
758	    renderContactsList();
759	}
