820	// ===== 发送消息 =====
821	function sendCurrentMessage() {
822	    const content = msgInput.value.trim();
823	    if (!content || !currentChat) return;
824	    msgInput.value = '';
825	
826	    const msgId = generateMsgId();
827	    const contact = contacts.get(currentChat);
828	
829	    // 保存到本地联系人消息列表
830	    if (!contact.messages) contact.messages = [];
831	    contact.messages.push({
832	        from: 'me',
833	        content: content,
834	        msg_id: msgId,
835	        timestamp: new Date().toISOString(),
836	        status: 'sending',
837	    });
838	    renderMessages(currentChat);
839	
840	    pendingMessages.set(msgId, { content, uuid: currentChat, status: 'sending' });
841	
842	    // 判断发送路径：
843	    //   - 主动发起方：有 chat WS（直接连对方后端 /ws/chat），通过它发送
844	    //   - 被动接收方：没有 chat WS，通过 control WS 发给自己后端，
845	    //                 自己后端复用发起方建立的 chat WS 回传给对方
846	    const chatWs = activeChats.get(currentChat);
847	    if (chatWs && chatWs.readyState === WebSocket.OPEN) {
848	        chatWs.send(JSON.stringify({
849	            type: 'chat',
850	            msg_id: msgId,
851	            content: content,
852	        }));
853	        // chat WS 直连绕过自己后端，需额外通知自己后端保存消息
854	        controlWs.send(JSON.stringify({
855	            type: 'save_message',
856	            peer_uuid: currentChat,
857	            sender: 'me',
858	            content: content,
859	            msg_id: msgId,
860	        }));
861	    } else {
862	        controlWs.send(JSON.stringify({
863	            type: 'chat_message',
864	            to_uuid: currentChat,
865	            msg_id: msgId,
866	            content: content,
867	        }));
868	    }
869	
870	    // 5秒超时：没收到 ACK 则标记失败
871	    setTimeout(() => {
872	        const pending = pendingMessages.get(msgId);
873	        if (pending && pending.status === 'sending') {
874	            pending.status = 'failed';
875	            pendingMessages.set(msgId, pending);
876	            if (currentChat) renderMessages(currentChat);
877	        }
878	    }, 5000);
879	}
