925	async function sendFile(uuid, file) {
926	    const CHUNK_SIZE = 64 * 1024; // 64KB
927	    const transferId = 't_' + myInfo.uuid + '_' + Date.now();
928	    const totalChunks = Math.ceil(file.size / CHUNK_SIZE);
929	
930	    // 通过聊天 WS 发 file_request
931	    const ws = activeChats.get(uuid);
932	    if (!ws) {
933	        showToast('未连接到对方，请先建立聊天');
934	        return;
935	    }
936	
937	    ws.send(JSON.stringify({
938	        type: 'file_request',
939	        transfer_id: transferId,
940	        file_name: file.name,
941	        file_size: file.size,
942	        chunk_size: CHUNK_SIZE,
943	        total_chunks: totalChunks,
944	        resume: false,
945	    }));
946	
947	    // 等待 file_response（通过 control ws 回调继续）
948	    addSystemMessage(uuid, `发送文件: ${file.name} (${formatSize(file.size)})`);
949	
950	    // 开始发送分片
951	    window._pendingFileTransfers = window._pendingFileTransfers || {};
952	    window._pendingFileTransfers[transferId] = { file, uuid, totalChunks, CHUNK_SIZE, transferId, currentChunk: 0 };
953	
954	    // 等待对方响应后开始发送分片
955	    const originalHandler = handleFileRequestResponse;
956	    const onceHandler = (msg) => {
957	        if (msg.transfer_id === transferId) {
958	            if (msg.accepted) {
959	                startChunkUpload(transferId);
960	            }
961	            // 恢复原始处理器
962	            window._fileResponseHandler = originalHandler;
963	        }
964	    };
965	    window._fileResponseHandler = (msg) => {
966	        originalHandler(msg);
967	        onceHandler(msg);
968	    };
969	}
970	
971	function handleFileRequestResponse(msg) {
972	    if (window._fileResponseHandler) {
973	        window._fileResponseHandler(msg);
974	    } else if (msg.accepted) {
975	        // 查找匹配的传输并开始上传
976	        const transfers = window._pendingFileTransfers || {};
977	        for (const [tid, t] of Object.entries(transfers)) {
978	            if (!t.started) {
979	                t.started = true;
980	                startChunkUpload(tid);
981	                break;
982	            }
983	        }
984	    }
985	}
986	
987	async function startChunkUpload(transferId) {
988	    const t = window._pendingFileTransfers?.[transferId];
989	    if (!t) return;
990	
991	    const peer = onlinePeers.get(t.uuid);
992	    if (!peer) {
993	        showToast('对方不在线，无法发送文件');
994	        return;
995	    }
996	
997	    const file = t.file;
998	    const CHUNK_SIZE = t.CHUNK_SIZE;
999	    const totalChunks = t.totalChunks;
1000	
1001	    for (let i = t.currentChunk; i < totalChunks; i++) {
1002	        const start = i * CHUNK_SIZE;
1003	        const end = Math.min(start + CHUNK_SIZE, file.size);
1004	        const blob = file.slice(start, end);
1005	        const dataB64 = await readAsBase64(blob);
1006	
1007	        let retries = 0;
1008	        let success = false;
1009	
1010	        while (retries < 3 && !success) {
1011	            try {
1012	                const peerPort = peer.ws_port || 50002;
1013	            const resp = await fetch(`http://${peer.ip}:${peerPort}/api/transfer/chunk`, {
1014	                    method: 'POST',
1015	                    headers: { 'Content-Type': 'application/json' },
1016	                    body: JSON.stringify({
1017	                        transfer_id: transferId,
1018	                        chunk_index: i,
1019	                        data: dataB64,
1020	                    }),
1021	                });
1022	                if (resp.ok) {
1023	                    success = true;
1024	                    t.currentChunk = i + 1;
1025	                } else {
1026	                    retries++;
1027	                }
1028	            } catch (e) {
1029	                retries++;
1030	            }
1031	        }
1032	
1033	        if (!success) {
1034	            addSystemMessage(t.uuid, '文件传输中断，等待对方重新上线');
1035	            return; // 传输暂停，等待后续续传
1036	        }
1037	    }
1038	
1039	    // 完成
1040	    try {
1041	        const peerPort = peer.ws_port || 50002;
1042	        await fetch(`http://${peer.ip}:${peerPort}/api/transfer/complete`, {
1043	            method: 'POST',
1044	            headers: { 'Content-Type': 'application/json' },
1045	            body: JSON.stringify({ transfer_id: transferId }),
1046	        });
1047	        addSystemMessage(t.uuid, `文件 ${file.name} 发送完成 ✓`);
1048	    } catch (e) {
1049	        addSystemMessage(t.uuid, '文件传输完成确认失败');
1050	    }
1051	
1052	    delete window._pendingFileTransfers?.[transferId];
1053	}
1054	
1055	function readAsBase64(blob) {
1056	    return new Promise((resolve) => {
1057	        const reader = new FileReader();
1058	        reader.onloadend = () => {
1059	            const result = reader.result;
1060	            // 去掉 "data:...;base64," 前缀
1061	            const b64 = result.split(',')[1] || result;
1062	            resolve(b64);
1063	        };
1064	        reader.readAsDataURL(blob);
1065	    });
1066	}
1067	
1068	// ===== 文件传输弹窗 =====
