1071	    fileModalBody.innerHTML = `
1072	        <p><strong>${esc(msg.from_name)}</strong> 想发送文件:</p>
1073	        <p>📄 ${esc(msg.file_name)} (${formatSize(msg.file_size)})</p>`;
1074	    fileModalButtons.innerHTML = `
1075	        <button id="btn-file-accept" class="btn-primary">接收</button>
1076	        <button id="btn-file-reject">拒绝</button>`;
1077	    fileModalOverlay.style.display = '';
1078	
