1083	            accepted: true,
1084	        }));
1085	        fileModalOverlay.style.display = 'none';
1086	    });
1087	    $('btn-file-reject').addEventListener('click', () => {
1088	        controlWs.send(JSON.stringify({
1089	            type: 'file_response',
1090	            transfer_id: msg.transfer_id,
1091	            accepted: false,
1092	        }));
1093	        fileModalOverlay.style.display = 'none';
1094	    });
1095	}
1096	
1097	// ===== 昵称编辑弹窗 =====
1098	function showEditNameModal() {
1099	    modalNameInput.value = myInfo.name;
1100	    modalOverlay.style.display = '';
1101	    modalNameInput.focus();
1102	}
