1108	    if (!newName || newName === myInfo.name) {
1109	        hideEditNameModal();
1110	        return;
1111	    }
1112	    controlWs.send(JSON.stringify({ type: 'update_name', name: newName }));
1113	    myInfo.name = newName;
1114	    $('my-name-label').textContent = newName;
1115	    hideEditNameModal();
