1128	    try {
1129	        const d = new Date(ts);
1130	        return d.toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' });
1131	    } catch (e) { return ''; }
1132	}
1133	function formatSize(bytes) {
1134	    if (bytes < 1024) return bytes + ' B';
1135	    if (bytes < 1048576) return (bytes / 1024).toFixed(1) + ' KB';
1136	    return (bytes / 1048576).toFixed(1) + ' MB';
